function build_dclink2_ripple()
%BUILD_DCLINK2_RIPPLE Create dclink2_ripple.slx from scratch.
%
%   Standalone model of DC link 2 with PI controller 2 and a resonant term
%   at the DC link 1 ripple frequency. All parameters come from
%   dclink2_ripple_params.m (model workspace data source). The model is
%   generated by this script so that its structure is reviewable as text;
%   re-run it after changing the structure, not for parameter changes.
%
%   Signals (logged): vdc1, vdc2, iL, m, mRes (resonant part of m).

    here  = fileparts(mfilename('fullpath'));
    model = 'dclink2_ripple';
    file  = fullfile(here, [model '.slx']);
    if bdIsLoaded(model), close_system(model, 0); end
    if isfile(file), delete(file); end

    new_system(model);
    cleanup = onCleanup(@() close_system(model, 0));

    set_param(model, 'Solver', 'ode23tb', 'StopTime', '1', 'MaxStep', 'Ts/4', ...
        'RelTol', '1e-6', 'SignalLogging', 'on', 'SignalLoggingName', 'logsout', ...
        'SaveOutput', 'off', 'SaveTime', 'off', 'SaveState', 'off', 'ReturnWorkspaceOutputs', 'on');

    mw = get_param(model, 'ModelWorkspace');
    mw.DataSource = 'MATLAB File';
    mw.FileName = 'dclink2_ripple_params.m';

    b = @(lib, name, pos, varargin) add_block(lib, [model '/' name], 'Position', pos, varargin{:});

    %% DC link 1 with ripple (not measured)
    b('simulink/Sources/Sine Wave', 'DC link 1', [40 330 80 370], ...
        'Amplitude', 'Vdc1Rip', 'Bias', 'Vdc1', 'Frequency', '2*pi*fRip', 'SampleTime', '0');

    %% Setpoint and measurement
    b('simulink/Sources/Constant', 'VbuckSet', [40 95 100 125], 'Value', 'VbuckSet');
    b('simulink/Discrete/Zero-Order Hold', 'ADC', [880 175 915 205], 'SampleTime', 'Ts');
    b('simulink/Math Operations/Sum', 'Error', [150 100 170 140], 'Inputs', '+-', 'IconShape', 'round');

    %% PI controller 2
    b('simulink/Math Operations/Gain', 'Kp', [230 60 270 90], 'Gain', 'Kp');
    b('simulink/Discrete/Discrete-Time Integrator', 'Integral', [220 105 280 135], ...
        'gainval', 'Ki', 'IntegratorMethod', 'Integration: Forward Euler', 'SampleTime', 'Ts', ...
        'InitialCondition', 'm0', 'LimitOutput', 'on', 'UpperSaturationLimit', 'mMax', ...
        'LowerSaturationLimit', 'mMin');

    %% Resonant term at fRip
    b('simulink/Math Operations/Gain', 'Resonant enable', [220 170 270 200], 'Gain', 'resEnable');
    b('simulink/Discrete/Discrete Transfer Fcn', 'Resonant', [300 165 400 205], ...
        'Numerator', 'resNum', 'Denominator', 'resDen', 'SampleTime', 'Ts');
    set_param([model '/Resonant'], 'Description', ...
        'Kr*s/(s^2 + 2*wc*s + w0^2), Tustin with prewarping at w0 (dclink2_ripple_params.m)');

    b('simulink/Math Operations/Sum', 'Sum m', [440 95 460 175], 'Inputs', '+++', 'IconShape', 'rectangular');
    b('simulink/Discontinuities/Saturation', 'm limit', [490 120 520 150], ...
        'UpperLimit', 'mMax', 'LowerLimit', 'mMin');
    b('simulink/Discrete/Unit Delay', 'Computation delay', [550 117 585 153], ...
        'InitialCondition', 'm0', 'SampleTime', 'Ts');

    %% Buck power stage (averaged), x = [iL; vC]
    b('simulink/Math Operations/Product', 'Switch node', [640 125 670 165], 'Inputs', '**');
    b('simulink/Continuous/State-Space', 'LC filter + load', [710 125 820 165], ...
        'A', '[-RL/L, -1/L; 1/C, -1/(Rload*C)]', 'B', '[1/L; 0]', 'C', 'eye(2)', 'D', '[0; 0]', ...
        'InitialCondition', '[iL0; vC0]');
    b('simulink/Signal Routing/Demux', 'Demux', [850 125 855 165], 'Outputs', '2');
    b('simulink/Sinks/Terminator', 'iL end', [900 105 920 125]);
    b('simulink/Sinks/Terminator', 'vdc2 end', [960 135 980 155]);
    b('simulink/Sinks/Terminator', 'vdc1 end', [140 380 160 400]);

    %% Wiring
    l = @(src, dst) add_line(model, src, dst, 'autorouting', 'on');
    l('VbuckSet/1', 'Error/1');
    l('ADC/1', 'Error/2');
    l('Error/1', 'Kp/1');
    l('Error/1', 'Integral/1');
    l('Error/1', 'Resonant enable/1');
    l('Resonant enable/1', 'Resonant/1');
    l('Kp/1', 'Sum m/1');
    l('Integral/1', 'Sum m/2');
    hRes = l('Resonant/1', 'Sum m/3');
    l('Sum m/1', 'm limit/1');
    l('m limit/1', 'Computation delay/1');
    hM = l('Computation delay/1', 'Switch node/1');
    hVdc1 = l('DC link 1/1', 'Switch node/2');
    l('DC link 1/1', 'vdc1 end/1');
    l('Switch node/1', 'LC filter + load/1');
    l('LC filter + load/1', 'Demux/1');
    hIL = l('Demux/1', 'iL end/1');
    hV = l('Demux/2', 'vdc2 end/1');
    l('Demux/2', 'ADC/1');

    names = {hRes, 'mRes'; hM, 'm'; hVdc1, 'vdc1'; hIL, 'iL'; hV, 'vdc2'};
    for k = 1:size(names, 1)
        set_param(names{k, 1}, 'Name', names{k, 2});
        set_param(get_param(names{k, 1}, 'SrcPortHandle'), 'DataLogging', 'on');
    end

    a = Simulink.Annotation([model '/note']);
    a.Text = sprintf(['Standalone DC link 2 model. DC link 1 (not measured) carries a %s ripple.\n' ...
        'PI controller 2 (integral only) + resonant term at the ripple frequency removes it from DC link 2.\n' ...
        'Parameters: dclink2_ripple_params.m (model workspace). resEnable = 0: PI only.'], 'fRip');
    a.Position = [40 440 700 490];

    save_system(model, file);
    fprintf('Saved %s\n', file);
end
